const d=/^([-+]?)(\d+)(?:\.(\d+))?$/;function f(n){const t=d.exec(n.trim());if(!t)return null;const s=t[3]??"",c=BigInt(t[2]+s);return{units:t[1]==="-"?-c:c,scale:s.length}}function r({units:n,scale:t}){const s=n<0n,c=(s?-n:n).toString().padStart(t+1,"0"),i=c.slice(0,c.length-t),a=c.slice(c.length-t).replace(/0+$/,""),u=a?`${i}.${a}`:i;return s&&u!=="0"?`-${u}`:u}function o(n,t){const s=Math.max(n.scale,t.scale);return[n.units*10n**BigInt(s-n.scale),t.units*10n**BigInt(s-t.scale),s]}function x(n){return typeof n=="string"&&f(n)!==null}function e(n){return(n?f(n):null)??{units:0n,scale:0}}function m(n,t){const[s,c,i]=o(e(n),e(t));return r({units:s+c,scale:i})}function $(n,t){const[s,c,i]=o(e(n),e(t));return r({units:s-c,scale:i})}function h(n){const t=e(n);return r({units:t.units<0n?-t.units:t.units,scale:t.scale})}function y(n){return n.reduce((t,s)=>m(t,s),"0")}function g(n,t){const[s,c]=o(e(n),e(t));return s<c?-1:s>c?1:0}const p=n=>g(n,"0"),I=n=>p(n)===0;function B(n,t){return g(n,t)<=0?l(n):l(t)}function l(n){return r(e(n))}export{x as a,$ as b,g as c,h as d,m as e,I as i,B as m,l as n,y as s};
